CREATE TABLE native71_row(id TEXT PRIMARY KEY,run_id TEXT NOT NULL,boundary TEXT NOT NULL,source_path TEXT NOT NULL,source_file_sha256 TEXT NOT NULL,source_blob_oid TEXT NOT NULL,ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,native_id_field TEXT,native_id TEXT,raw_json TEXT NOT NULL,raw_sha256 TEXT NOT NULL,UNIQUE(run_id,source_path,pointer)) WITHOUT ROWID;
CREATE TABLE native71_slot(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES native71_row(id),owner_field TEXT NOT NULL,historical_owner_field TEXT,owner_role_status TEXT NOT NULL CHECK(owner_role_status IN ('resolved','mapping_unresolved')),locale TEXT NOT NULL CHECK(locale IN ('CHS','EN','JP')),raw_locator TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_main','resolved_medium','resolved_candidate_set','missing')),candidate_count INTEGER NOT NULL,selected_candidate_count INTEGER NOT NULL,UNIQUE(row_id,owner_field,locale)) WITHOUT ROWID;
CREATE TABLE native71_text(id TEXT PRIMARY KEY,slot_id TEXT NOT NULL REFERENCES native71_slot(id),source_path TEXT NOT NULL,source_file_sha256 TEXT NOT NULL,source_blob_oid TEXT NOT NULL,tier TEXT NOT NULL CHECK(tier IN ('main','medium')),pair_ordinal INTEGER NOT NULL,pointer TEXT NOT NULL,raw_text TEXT NOT NULL,raw_text_sha256 TEXT NOT NULL,selected INTEGER NOT NULL CHECK(selected IN (0,1)),UNIQUE(slot_id,source_path,pair_ordinal)) WITHOUT ROWID;
CREATE TABLE native71_relation(id TEXT PRIMARY KEY,row_id TEXT NOT NULL REFERENCES native71_row(id),relation_kind TEXT NOT NULL,source_field TEXT NOT NULL,source_pointer TEXT NOT NULL,raw_locator TEXT NOT NULL,candidate_namespace TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('resolved_unique','resolved_candidate_set','missing')),candidate_count INTEGER NOT NULL,search_complete INTEGER NOT NULL CHECK(search_complete=1),UNIQUE(row_id,relation_kind,source_pointer)) WITHOUT ROWID;
CREATE TABLE native71_candidate(id TEXT PRIMARY KEY,relation_id TEXT NOT NULL REFERENCES native71_relation(id),target_family TEXT NOT NULL,target_contract TEXT NOT NULL,target_parser TEXT NOT NULL,target_run TEXT NOT NULL,target_occurrence_id TEXT NOT NULL,target_source_path TEXT NOT NULL,target_source_pointer TEXT NOT NULL,target_native_id TEXT NOT NULL,target_raw_sha256 TEXT NOT NULL,UNIQUE(relation_id,target_run,target_occurrence_id)) WITHOUT ROWID;
CREATE TABLE native71_release(id INTEGER PRIMARY KEY CHECK(id=1),manifest_json TEXT NOT NULL) WITHOUT ROWID;
CREATE INDEX native71_slot_parent ON native71_slot(row_id);
CREATE INDEX native71_text_slot ON native71_text(slot_id);
CREATE INDEX native71_text_value ON native71_text(raw_text);
CREATE INDEX native71_relation_parent ON native71_relation(row_id);
CREATE INDEX native71_candidate_parent ON native71_candidate(relation_id);
CREATE TRIGGER native71_row_i BEFORE INSERT ON native71_row WHEN EXISTS(SELECT 1 FROM native71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_slot_i BEFORE INSERT ON native71_slot WHEN EXISTS(SELECT 1 FROM native71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_text_i BEFORE INSERT ON native71_text WHEN EXISTS(SELECT 1 FROM native71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_relation_i BEFORE INSERT ON native71_relation WHEN EXISTS(SELECT 1 FROM native71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_candidate_i BEFORE INSERT ON native71_candidate WHEN EXISTS(SELECT 1 FROM native71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_release_i BEFORE INSERT ON native71_release WHEN EXISTS(SELECT 1 FROM native71_release) BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_row_u BEFORE UPDATE ON native71_row BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_slot_u BEFORE UPDATE ON native71_slot BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_text_u BEFORE UPDATE ON native71_text BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_relation_u BEFORE UPDATE ON native71_relation BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_candidate_u BEFORE UPDATE ON native71_candidate BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_release_u BEFORE UPDATE ON native71_release BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_row_d BEFORE DELETE ON native71_row BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_slot_d BEFORE DELETE ON native71_slot BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_text_d BEFORE DELETE ON native71_text BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_relation_d BEFORE DELETE ON native71_relation BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_candidate_d BEFORE DELETE ON native71_candidate BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
CREATE TRIGGER native71_release_d BEFORE DELETE ON native71_release BEGIN SELECT RAISE(ABORT,'immutable sealed Native Message 7.1');END;
